(function() {
    'use strict';

    class StressAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Gestion del Estres Organizacional';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    title: `Ronda 1 — Diagnóstico y Análisis`,
                    description: `Hospital Metropolitano reporta 42% de burnout, 38% de rotación y múltiples colapsos emocionales en 2025. Diseña tu primera intervención: invierte en diagnóstico, encuestas y primeras medidas de contención. Las decisiones preventivas generan más impacto estructural pero requieren mayor horizonte temporal.`
                },
                {
                    title: `Ronda 2 — Diseño de Solución`,
                    description: `Con el diagnóstico en mano, define las intervenciones de bienestar: apoyo psicológico, turnos más humanos y programas de formación. Equilibra inversión, reducción de turnos de 24h e incremento de personal. Cuidado con iniciativas cosméticas que no atacan las causas.`
                },
                {
                    title: `Ronda 3 — Implementación y Rediseño`,
                    description: `Rediseña procesos clave. Aquí el foco estructural es crítico: reorganización de equipos, protocolos de carga asistencial y rotación de servicios. Los resultados tardan, pero son los que sostienen la cultura.`
                },
                {
                    title: `Ronda 4 — Evaluación y Sostenibilidad`,
                    description: `Consolida el modelo: mide el impacto, ajusta y deja instalado un sistema de gestión del estrés sostenible. El objetivo final es un índice de burnout por debajo del 20% y una rotación menor al 20% sin sacrificar productividad.`
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2000000000,
                    burnoutIndex: 42,
                    rotation: 38,
                    productivity: 78,
                    engagement: 55,
                    burnoutHistory: [42],
                    rotationHistory: [38],
                    productivityHistory: [78]
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    wellnessBudget: 100,
                    staffingIncrease: 5,
                    shiftReduction: 10,
                    trainingHours: 4,
                    focus: `preventive`
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var phaseEl = document.getElementById('phaseLabel');
            if (titleEl) titleEl.innerText = round.title;
            if (textEl) textEl.innerText = round.description;
            if (phaseEl) phaseEl.innerText = round.title.split('—')[1] ? round.title.split('—')[1].trim() : '';
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var w = document.getElementById('wellnessInput');
            var s = document.getElementById('staffingInput');
            var sh = document.getElementById('shiftInput');
            var t = document.getElementById('trainingInput');
            var f = document.getElementById('focusInput');
            if (w) decisions.wellnessBudget = parseFloat(w.value);
            if (s) decisions.staffingIncrease = parseFloat(s.value);
            if (sh) decisions.shiftReduction = parseFloat(sh.value);
            if (t) decisions.trainingHours = parseFloat(t.value);
            if (f) decisions.focus = f.value;

            if (isNaN(decisions.wellnessBudget) || decisions.wellnessBudget < 0 || decisions.wellnessBudget > 800) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('wellness_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.staffingIncrease) || decisions.staffingIncrease < 0 || decisions.staffingIncrease > 30) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('staffing_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.shiftReduction) || decisions.shiftReduction < 0 || decisions.shiftReduction > 100) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('shift_warning'), 'warning');
                return false;
            }
            if (isNaN(decisions.trainingHours) || decisions.trainingHours < 0 || decisions.trainingHours > 40) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('training_warning'), 'warning');
                return false;
            }

            var totalCost = decisions.wellnessBudget * 1000000
                          + decisions.staffingIncrease * 25000000
                          + decisions.shiftReduction * 8000000
                          + decisions.trainingHours * 6000000;
            if (totalCost > window.mySimulation.state.domainState.cash) {
                window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var focusMult = 1.0;
            if (d.focus === 'preventive') focusMult = 1.15;
            else if (d.focus === 'structural') focusMult = 1.25;
            else if (d.focus === 'reactive') focusMult = 0.85;

            var wellnessEffect = Math.sqrt(d.wellnessBudget) * 0.35 * focusMult;
            var staffingEffect = d.staffingIncrease * 0.45;
            var shiftEffect = d.shiftReduction * 0.22 * focusMult;
            var trainingEffect = Math.sqrt(d.trainingHours) * 0.6;

            var burnoutReduction = wellnessEffect + staffingEffect * 0.8 + shiftEffect * 1.1 + trainingEffect * 0.6;
            var rotationReduction = staffingEffect * 0.9 + shiftEffect * 0.8 + wellnessEffect * 0.4;
            var productivityGain = trainingEffect * 1.2 + staffingEffect * 0.3 - (d.shiftReduction < 5 ? 1 : 0);

            if (d.focus === 'reactive' && state.currentPeriod >= 3) {
                burnoutReduction *= 0.6;
                rotationReduction *= 0.5;
            }

            var newBurnout = Math.max(5, ds.burnoutIndex - burnoutReduction);
            var newRotation = Math.max(4, ds.rotation - rotationReduction);
            var newProductivity = Math.min(100, Math.max(40, ds.productivity + productivityGain));

            if (d.wellnessBudget < 30 && d.staffingIncrease < 3 && d.shiftReduction < 10) {
                newBurnout = Math.min(80, newBurnout + 2.5);
                newRotation = Math.min(70, newRotation + 1.5);
            }

            var cost = d.wellnessBudget * 1000000
                     + d.staffingIncrease * 25000000
                     + d.shiftReduction * 8000000
                     + d.trainingHours * 6000000;

            var burnoutCostImpact = (ds.burnoutIndex - newBurnout) * 18000000;
            var rotationCostImpact = (ds.rotation - newRotation) * 22000000;
            var netSavings = burnoutCostImpact + rotationCostImpact;

            ds.cash = ds.cash - cost + netSavings;
            ds.burnoutIndex = Math.round(newBurnout * 10) / 10;
            ds.rotation = Math.round(newRotation * 10) / 10;
            ds.productivity = Math.round(newProductivity * 10) / 10;
            ds.engagement = Math.min(100, ds.engagement + (burnoutReduction * 0.6));

            ds.burnoutHistory.push(ds.burnoutIndex);
            ds.rotationHistory.push(ds.rotation);
            ds.productivityHistory.push(ds.productivity);

            // Persist composite 0-100 score into domainState for the grading/reporting
            // layer (results_utils.php reads domainState.performance.overallScore -> score).
            var _sc = this._score(ds.burnoutIndex, ds.rotation, ds.productivity);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: this._grade(_sc) };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                cost: cost,
                savings: Math.round(netSavings),
                netCost: Math.round(cost - netSavings),
                burnoutIndex: ds.burnoutIndex,
                rotation: ds.rotation,
                productivity: ds.productivity,
                focus: d.focus,
                score: _sc,
                overallScore: _sc
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => '$' + Math.round(v).toLocaleString('es-CO'));
            uiManager.bind('burnoutDisplay', 'domainState.burnoutIndex',
                (v) => (Math.round(v * 10) / 10) + '%');
            uiManager.bind('rotationDisplay', 'domainState.rotation',
                (v) => (Math.round(v * 10) / 10) + '%');
            uiManager.bind('productivityDisplay', 'domainState.productivity',
                (v) => Math.round(v * 10) / 10);
        }

        getChartConfig() {
            return {
                burnoutChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Burnout (%)',
                                data: [],
                                borderColor: '#e63946',
                                backgroundColor: 'rgba(230,57,70,0.12)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25
                            },
                            {
                                label: 'Rotacion (%)',
                                data: [],
                                borderColor: '#f4a261',
                                backgroundColor: 'rgba(244,162,97,0.10)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25
                            },
                            {
                                label: 'Productividad',
                                data: [],
                                borderColor: '#2a9d8f',
                                backgroundColor: 'rgba(42,157,143,0.10)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.25
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: false } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = state.domainState;
            var labels = ds.burnoutHistory.map((_, i) => i === 0 ? 'Base' : 'R' + i);
            return {
                burnoutChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.burnoutHistory },
                        { data: ds.rotationHistory },
                        { data: ds.productivityHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.burnoutIndex > 35 && state.currentPeriod >= 2) return window.mySimulation.t('hint_high_burnout');
            if (results.focus === 'reactive' && state.currentPeriod >= 3) return window.mySimulation.t('hint_reactive');
            if (state.decisions.wellnessBudget < 40 && state.currentPeriod >= 2) return window.mySimulation.t('hint_low_wellness');
            if (results.productivity < 70) return window.mySimulation.t('hint_low_productivity');
            if (results.rotation < 15 && results.burnoutIndex < 20) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'decisions.wellnessBudget', label: 'Bienestar (M)', i18nKey: 'col_wellness' },
                { key: 'decisions.staffingIncrease', label: 'Personal %', i18nKey: 'col_staffing', formatter: (v) => v + '%' },
                { key: 'decisions.shiftReduction', label: 'Turnos %', i18nKey: 'col_shift', formatter: (v) => v + '%' },
                { key: 'decisions.trainingHours', label: 'Formacion', i18nKey: 'col_training' },
                { key: 'decisions.focus', label: 'Foco', i18nKey: 'col_focus' },
                { key: 'results.burnoutIndex', label: 'Burnout', i18nKey: 'col_burnout', formatter: (v) => v + '%' },
                { key: 'results.rotation', label: 'Rotacion', i18nKey: 'col_rotation', formatter: (v) => v + '%' },
                { key: 'results.netCost', label: 'Coste Neto', i18nKey: 'col_netcost', formatter: (v) => '$' + Number(v).toLocaleString('es-CO') }
            ];
        }

        getPresets() { return null; }

        _score(burnout, rotation, productivity) {
            var bc = Math.max(0, Math.min(100, (45 - burnout) / 35 * 100));
            var rc = Math.max(0, Math.min(100, (40 - rotation) / 32 * 100));
            var pc = Math.max(0, Math.min(100, (productivity - 60) / 30 * 100));
            return Math.max(0, Math.min(100, Math.round(0.40 * bc + 0.35 * rc + 0.25 * pc)));
        }

        _grade(score) {
            if (score >= 80) return 'Excelente';
            if (score >= 60) return 'Bueno';
            if (score >= 40) return 'Aceptable';
            return 'Insuficiente';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var burnout = last.results ? last.results.burnoutIndex : 42;
            var rotation = last.results ? last.results.rotation : 38;
            var productivity = last.results ? last.results.productivity : 78;

            var performance = 'Insuficiente';
            if (burnout < 30 && rotation < 25) performance = 'Aceptable';
            if (burnout < 22 && rotation < 20 && productivity > 82) performance = 'Bueno';
            if (burnout < 18 && rotation < 16 && productivity > 85) performance = 'Excelente';

            var t = function(k) { return window.mySimulation.t(k); };
            var insights = [];
            if (burnout < 20) insights.push(t('sum_burnout_low'));
            if (burnout >= 30) insights.push(t('sum_burnout_high'));
            if (rotation < 18) insights.push(t('sum_rotation_low'));
            if (productivity < 75) insights.push(t('sum_productivity_low'));

            return {
                burnoutFinal: burnout,
                rotationFinal: rotation,
                productivityFinal: productivity,
                overallScore: this._score(burnout, rotation, productivity),
                totalPeriods: history.length,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var perf = summary.performance || this._grade(score);
            var tierKey = { 'Excelente': 'tier_excelente', 'Bueno': 'tier_bueno', 'Aceptable': 'tier_aceptable', 'Insuficiente': 'tier_insuficiente' }[perf];
            var perfL = tierKey ? t(tierKey) : perf;
            var color = score >= 80 ? '#2a9d8f' : (score >= 60 ? '#e9c46a' : (score >= 40 ? '#f4a261' : '#e63946'));
            var kpis = [
                [t('burnout_label'), (typeof summary.burnoutFinal === 'number') ? (summary.burnoutFinal + '%') : '-'],
                [t('rotation_label'), (typeof summary.rotationFinal === 'number') ? (summary.rotationFinal + '%') : '-'],
                [t('productivity_label'), (typeof summary.productivityFinal === 'number') ? summary.productivityFinal : '-']
            ];
            var kpiRow = kpis.map(function(k) { return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>'; }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';
            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('completion_heading') + '</h4>' +
                '<div style="font-size:2.6rem;font-weight:800;color:' + color + ';">' + score + '/100</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('overall_score_label') + '</p>' +
                '<p style="font-weight:700;color:' + color + ';">' + perfL + '</p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
                insBlock +
                '<hr class="my-3"><p class="text-muted">' + t('thanks_msg') + '</p></div>';
        }

        getTranslations() {
            return {
                es: {
                    title: `Gestión del Estrés Organizacional`,
                    subtitle: `Hospital Metropolitano — Prevención de Burnout`,
                    period_label: `Ronda`,
                    period_of: `de`,
                    burnout_label: `Índice de Burnout`,
                    rotation_label: `Rotación Enfermería`,
                    productivity_label: `Productividad`,
                    cash_label: `Presupuesto (COP)`,
                    decisions_heading: `Decisiones de la Ronda`,
                    wellness_label: `Inversión Bienestar (COP millones)`,
                    staffing_label: `Incremento Personal (%)`,
                    shift_label: `Reducción Turnos 24h (%)`,
                    training_label: `Horas Formación / empleado`,
                    focus_label: `Foco Estratégico`,
                    focus_preventive: `Preventivo`,
                    focus_reactive: `Reactivo`,
                    focus_structural: `Estructural`,
                    submit_btn: `Ejecutar Ronda`,
                    undo_btn: `Deshacer`,
                    history_heading: `Historial de Intervenciones`,
                    chart_heading: `Evolución del Bienestar Organizacional`,
                    wellness_warning: `La inversión en bienestar debe estar entre 0 y 800 millones COP`,
                    staffing_warning: `El incremento de personal debe estar entre 0% y 30%`,
                    shift_warning: `La reducción de turnos debe estar entre 0% y 100%`,
                    training_warning: `Las horas de formación deben estar entre 0 y 40`,
                    budget_warning: `Presupuesto insuficiente para esta combinación de decisiones`,
                    hint_high_burnout: `El burnout sigue elevado. Considera combinar reducción de turnos con incremento de personal.`,
                    hint_reactive: `Un enfoque reactivo pierde eficacia con el tiempo. Cambia a preventivo o estructural.`,
                    hint_low_wellness: `Invertir poco en bienestar limita el efecto sobre la cultura y el compromiso.`,
                    hint_low_productivity: `La productividad ha caído: revisa si los recortes de turnos vinieron acompañados de rediseño de procesos.`,
                    hint_excellent: `Indicadores excelentes. Consolida el modelo y documenta las buenas prácticas.`,
                    col_wellness: `Bienestar (M)`,
                    col_staffing: `Personal %`,
                    col_shift: `Turnos %`,
                    col_training: `Formación`,
                    col_focus: `Foco`,
                    col_burnout: `Burnout`,
                    col_rotation: `Rotación`,
                    col_netcost: `Coste Neto`,
                    completion_heading: `Evaluación Final`,
                    overall_score_label: `Puntaje General`,
                    thanks_msg: `Gracias por participar.`,
                    tier_insuficiente: `Insuficiente`,
                    tier_aceptable: `Aceptable`,
                    tier_bueno: `Bueno`,
                    tier_excelente: `Excelente`,
                    sum_burnout_low: `Redujiste el burnout a niveles sostenibles. Documenta las practicas para escalarlas.`,
                    sum_burnout_high: `El burnout sigue alto: revisa si las intervenciones atacaron causas estructurales.`,
                    sum_rotation_low: `Rotacion controlada: buena senal de retencion y compromiso.`,
                    sum_productivity_low: `Productividad baja: posible exceso de recortes sin rediseno de procesos.`
                },
                en: {
                    title: `Organizational Stress Management`,
